def text(r,f='body'):
 return next((x['new'] for x in cs.get(r,{}).get('field_changes',[]) if x['field']==f),n[r]['data'].get(f))
def setv(r,f,s,sup,why):
 if r not in cs: cs[r]=dict(target_revision=r,expectedVersion=n[r]['version'],kind=n[r]['kind'],field_changes=[],supporting_versions=[],reason=why)
 c=cs[r];c['field_changes']=[x for x in c['field_changes'] if x['field']!=f]+[dict(field=f,old=n[r]['data'].get(f),new=s)]
 c['supporting_versions']=list(dict.fromkeys(c['supporting_versions']+sup));c['reason']+=' '+why if why not in c['reason'] else ''
def sub(r,a,b,sup,why,f='body'):
 s=text(r,f);assert s.count(a)==1,(r,a);setv(r,f,s.replace(a,b),sup,why)
