for c in cs.values():
 c['mechanical_rule']='Settled field decisions. Preserve every unspecified field, original rationale, disposition, evidence status, origins and existing evidence. Append exact amendment_caveat. Materialize full literal API and individually review evidence rebindings before approval; no runtime inference.'
 c['amendment_caveat']='T-0790 2026-10-06: '+c['reason']+' Endast accepterat återbruk; ingen ny original-, katalog- eller nätläsning. Äldre motsägande formulering inom exakt rättat fält är överspelad, men råreservationer och historiska granskningsomfång består.'
# exact planned new heads, no implicit runtime binding.
heads={c['target_revision'].rsplit('@',1)[0]:c['expectedVersion']+1 for c in cs.values()}
def final(r):
 o,ver=r.rsplit('@',1);return o+'@'+str(heads.get(o,int(ver)))
for row in v['individual_table']:
 old=row['object_id']+'@'+str(row['old_version']);c=cs.get(old)
 row['disposition']='revise' if c else 'retain';row['final_revision']=final(old)
 row['new_outcome']=next((f['new'] for f in c['field_changes'] if f['field']=='outcome'),row['old_outcome']) if c else row['old_outcome']
 if c:row['individual_rationale']+=' '+c['reason']
 if row['person']=='P-0212' and row['item']=='PK-06':row['individual_rationale']='Alla tio teman har individuellt bedömda belägg, luckor och möjliga vägar; STYRKT enligt PK06-definitionen. Öppna teman innebär inte automatiskt PK06-fel. V1:s motsatta slutsats återtas uttryckligen; PK03/04/08 håller livsbilden failed.'
 if row['person']=='P-0211' and row['item'] in ['SYN','PK-03','PK-04','PK-10']:row['individual_rationale']+=' Även dotterns accepterade födelse1964 konsolideras utan födelseort eller bostadsinferens.'
 row['supporting_versions']=list(dict.fromkeys(row['supporting_versions']+(c['supporting_versions'] if c else [])))
 row['final_supporting_versions']=list(dict.fromkeys(map(final,row['supporting_versions'])))
for rv in v['six_life_reviews']:
 p=rv['data']['subject_id']; rows=[r for r in v['individual_table'] if r['person']==p]
 rv['expectedVersion']=None; rv['data']['body']='T-0790 individuell livsbildsgranskning 2026-10-06; endast accepterat befintligt underlag.\n\n'+ '\n'.join(r['item']+' — '+r['new_outcome']+'. '+r['individual_rationale'] for r in rows)+'\n\nSlututfall: '+rv['data']['outcome']+'. '
 rv['data']['body']+=('PCD2026-09-09-029:s exakta obligatoriska K09-passage för denna person återstår hos T-0034; dataminimering gör den inte utförd.' if p in ['P-0004','P-0210','P-0005','P-0006'] else 'Individuellt minimerat omfång är sakligt fullgjort med accepterade1938/1962/1964/2017-ankare; Evy ingår inte i PCD029:s obligatoriska sjupersonspassage. Prövade råreservationer kvarstår, och ingen nutida levandestatus fastställs.' if p=='P-0211' else 'PK03/04/08 förblir underkända för de specificerade materiella livs-, relations- och åtkomstluckorna. T-0359, T-0362 och T-0795 äger exakt sina befintliga begränsade frågor; inga nya källor har öppnats.')
 rv['data']['body']+=' Återöppna berörda bedömningar vid relevant ny accepterad evidens, verifierad specifik åtkomstgräns eller uttrycklig ändring av personomfånget. Identitet, trädverkan, OWNER_CONFIRMED och accepterade relationer består. Legacy helkontraktsgranskning behåller historiskt omfång; task DONE är inte personpass.'
 rv['caveat']='Ingen ny original-, katalog- eller nätläsning. Personbundna tids-/plats-/fältgränser, gemensamma uppgiftsled och prövade råreservationer består. Denna granskning gäller endast livsbildsnivån.'
 rv['evidence_versions']=list(dict.fromkeys(final(x) for x in rv['evidence_versions']+sum((r['supporting_versions'] for r in rows),[])))
 rv['evidence']=[dict(object=x.rsplit('@',1)[0],version=int(x.rsplit('@',1)[1]),role='supports',note='T0790 individuell livsbildsprövning; exakt aktuell accepterad eller i detta paket beslutad revision, ingen ny oberoende källröst.') for x in rv.pop('evidence_versions')]
 rv['evidenceStatus']=rv.pop('evidence_status');rv['origins']=[]
